es_get_ids') ); add_action( 'wp_ajax_nopriv_qqworld-collector-static-cache-refreshing-taxonomies-get-ids', array($this, 'refreshing_taxonomies_get_ids') ); add_action( 'wp_ajax_qqworld-collector-static-cache-refreshing-taxonomies-single', array($this, 'refreshing_taxonomies_single') ); add_action( 'wp_ajax_nopriv_qqworld-collector-static-cache-refreshing-taxonomies-single', array($this, 'refreshing_taxonomies_single') ); add_action( 'wp_ajax_qqworld-collector-static-cache-refreshing-upload-exclude-ids', array($this, 'refreshing_upload_exclude_ids') ); add_action( 'wp_ajax_nopriv_qqworld-collector-static-cache-refreshing-upload-exclude-ids', array($this, 'refreshing_upload_exclude_ids') ); add_action( 'wp_ajax_qqworld-collector-static-cache-wiping-homepage', array($this, 'wiping_homepage') ); add_action( 'wp_ajax_nopriv_qqworld-collector-static-cache-wiping-homepage', array($this, 'wiping_homepage') ); add_action( 'wp_ajax_qqworld-collector-static-cache-wiping-post-type-archive', array($this, 'wiping_post_type_archive') ); add_action( 'wp_ajax_nopriv_qqworld-collector-static-cache-wiping-post-type-archive', array($this, 'wiping_post_type_archive') ); add_action( 'wp_ajax_qqworld-collector-static-cache-wiping-post-type', array($this, 'wiping_post_type') ); add_action( 'wp_ajax_nopriv_qqworld-collector-static-cache-wiping-post-type', array($this, 'wiping_post_type') ); add_action( 'wp_ajax_qqworld-collector-static-cache-wiping-taxonomies', array($this, 'wiping_taxonomies') ); add_action( 'wp_ajax_nopriv_qqworld-collector-static-cache-wiping-taxonomies', array($this, 'wiping_taxonomies') ); add_action( 'wp_ajax_qqworld-collector-static-cache-restart-wiping', array($this, 'restart_wiping') ); add_action( 'wp_ajax_nopriv_qqworld-collector-static-cache-restart-wiping', array($this, 'restart_wiping') ); add_action( 'wp_ajax_qqworld-collector-static-cache-create-cache-link-cdn', array($this, 'create_cache_link_cdn') ); add_action( 'wp_ajax_nopriv_qqworld-collector-static-cache-create-cache-link-cdn', array($this, 'create_cache_link_cdn') ); } public function refreshing_homepage() { $respond = $this->core->home->make_cache(); $results = array( 'success' => $respond ); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function refreshing_post_type_archive() { foreach ($this->options->qc_static_cache_post_types as $post_type) { $this->core->post_type_archive->make_cache($post_type); } $results = array( 'success' => true ); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function refreshing_post_type() { $exclude = get_option('qqworld-collector-static-cache-refreshing-post-type-exclude', array()); $exclude = $exclude ? $exclude : array(); foreach ($this->options->qc_static_cache_post_types as $post_type) { for ($paged=0; $paged<=99999; $paged++) { $args = array( 'post_type' => $post_type, 'post_status' => 'publish', 'posts_per_page' => 100, 'offset' => 100*$paged, 'exclude' => $exclude ); $posts = get_posts($args); if (!empty($posts)) { foreach ($posts as $post) { $this->core->singular->make_cache($post->ID); $exclude[] = $post->ID; } update_option('qqworld-collector-static-cache-refreshing-post-type-exclude', $exclude); } else { break; } } } $results = array( 'success' => true ); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function refreshing_taxonomies() { $exclude = get_option('qqworld-collector-static-cache-refreshing-taxonomies-exclude', array()); $exclude = $exclude ? $exclude : array(); foreach ($this->options->qc_static_cache_taxonomies as $taxonomy) { for ($paged=0; $paged<=99999; $paged++) { $args = array( 'taxonomy' => $taxonomy, 'hide_empty' => true, 'number' => 100, 'offset' => 100*$paged, 'exclude' => $exclude ); $terms = get_terms($args); if (!empty($terms)) { foreach ($terms as $term) { $this->core->archive->make_cache($term->term_id, $taxonomy); $exclude[] = $term->term_id; } update_option('qqworld-collector-static-cache-refreshing-taxonomies-exclude', $exclude); } else { break; } } } $results = array( 'success' => true ); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function restart_refreshing() { if (!isset($_POST['mode']) || empty($_POST['mode'])) die(); update_option('qqworld-collector-static-cache-refreshing-'.$_POST['mode'].'-exclude', array()); $results = array( 'success' => true ); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function refreshing_post_type_get_ids() { $exclude = get_option('qqworld-collector-static-cache-refreshing-post-type-exclude', array()); $exclude = $exclude ? $exclude : array(); $ids = array(); foreach ($this->options->qc_static_cache_post_types as $post_type) { for ($paged=0; $paged<=99999; $paged++) { $args = array( 'post_type' => $post_type, 'post_status' => 'publish', 'posts_per_page' => 100, 'offset' => 100*$paged, 'exclude' => $exclude ); $posts = get_posts($args); if (!empty($posts)) { foreach ($posts as $post) { $ids[] = $post->ID; } } else { break; } } } if ($ids) { $results = array( 'success' => true, 'ids' => $ids, 'msg' => sprintf(__('There are %d posts cache to be refreshed.', $this->text_domain), count($ids)) ); } else { $results = array( 'success' => false, 'msg' => __('There are no more posts to refresh the cache.', $this->text_domain) ); } print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function refreshing_post_type_single() { $this->core->singular->make_cache($_POST['ID']); $results = array( 'success' => true, 'ID' => $_POST['ID'], 'msg' => sprintf(__('<strong>%s</strong> has been refreshed.', $this->text_domain), get_the_title($_POST['ID']) . ' ('.$_POST['ID'].')') ); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function refreshing_taxonomies_get_ids() { $exclude = get_option('qqworld-collector-static-cache-refreshing-taxonomies-exclude', array()); $exclude = $exclude ? $exclude : array(); $ids = array(); foreach ($this->options->qc_static_cache_taxonomies as $taxonomy) { for ($paged=0; $paged<=99999; $paged++) { $args = array( 'taxonomy' => $taxonomy, 'hide_empty' => true, 'number' => 100, 'offset' => 100*$paged, 'exclude' => $exclude ); $terms = get_terms($args); if (!empty($terms)) { foreach ($terms as $term) { $ids[] = array($term->term_id, $taxonomy); } } else { break; } } } if ($ids) { $results = array( 'success' => true, 'ids' => $ids, 'msg' => sprintf(__('There are %d terms cache to be refreshed.', $this->text_domain), count($ids)) ); } else { $results = array( 'success' => false, 'msg' => __('There are no more terms to refresh the cache.', $this->text_domain) ); } print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function refreshing_taxonomies_single() { list($term_id, $taxonomy) = $_POST['ID']; $this->core->archive->make_cache($term_id, $taxonomy); $term = get_term_by('id', $term_id, $taxonomy); $results = array( 'success' => true, 'ID' => $_POST['ID'], 'msg' => sprintf(__('<strong>%s</strong> has been refreshed.', $this->text_domain), $term->name . ' ('.$term_id.')') ); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function refreshing_upload_exclude_ids() { extract($_POST); $exclude = get_option('qqworld-collector-static-cache-refreshing-'.$mode.'-exclude', array()); $exclude = $exclude ? $exclude : array(); $exclude = array_merge($exclude, $ids); update_option('qqworld-collector-static-cache-refreshing-'.$mode.'-exclude', $exclude); $results = array( 'success' => true, 'ids' => $ids, 'exclude' => $exclude ); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function wiping_homepage() { switch ($this->options->qc_static_cache_mode) { case 'half': $filepath = WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'static-cache' . DIRECTORY_SEPARATOR . md5('/'); break; case 'pure': $filepath = ABSPATH . DIRECTORY_SEPARATOR . 'index.html'; break; } if (file_exists($filepath)) { $status = unlink($filepath); } else $status = true; $results = array( 'success' => true ); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function wiping_post_type_archive() { $results = array( 'success' => true ); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function wiping_post_type() { $exclude = get_option('qqworld-collector-static-cache-wiping-post-type-exclude', array()); $exclude = $exclude ? $exclude : array(); foreach ($this->options->qc_static_cache_post_types as $post_type) { for ($paged=0; $paged<=99999; $paged++) { $args = array( 'post_type' => $post_type, 'post_status' => 'publish', 'posts_per_page' => 100, 'offset' => 100*$paged, 'exclude' => $exclude ); $posts = get_posts($args); if (!empty($posts)) { foreach ($posts as $post) { $this->core->remove->singular($post->ID); $exclude[] = $post->ID; } update_option('qqworld-collector-static-cache-wiping-post-type-exclude', $exclude); } else { break; } } } $results = array( 'success' => true ); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function wiping_taxonomies() { $exclude = get_option('qqworld-collector-static-cache-wiping-taxonomies-exclude', array()); $exclude = $exclude ? $exclude : array(); foreach ($this->options->qc_static_cache_taxonomies as $taxonomy) { for ($paged=0; $paged<=99999; $paged++) { $args = array( 'taxonomy' => $taxonomy, 'hide_empty' => false, 'number' => 100, 'offset' => 100*$paged, 'exclude' => $exclude ); $terms = get_terms($args); if (!empty($terms)) { foreach ($terms as $term) { $this->core->remove->archive($term->term_id, $taxonomy); $exclude[] = $term->term_id; } update_option('qqworld-collector-static-cache-wiping-taxonomies-exclude', $exclude); } else { break; } } } $results = array( 'success' => true ); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function restart_wiping() { if (!isset($_POST['mode']) || empty($_POST['mode'])) die(); update_option('qqworld-collector-static-cache-wiping-'.$_POST['mode'].'-exclude', array()); $results = array( 'success' => true ); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function create_cache_link_cdn() { switch ($_POST['mode']) { case 'homepage': $respond = $this->core->home->make_cache(); break; case 'taxonomies': $respond = $this->core->archive->make_cache(intval($_POST['query']['term_id']), $_POST['query']['taxonomy'], $_POST['query']['page']); break; case 'post_type': $respond = $this->core->singular->make_cache(intval($_POST['query']['post_id']), $_POST['query']['post_type'], $_POST['query']['page']); break; default: $respond = false; break; } $results = array( 'success' => $respond, 'post' => $_POST ); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } } ?>